const webhook = $('Webhook Chatbot').first().json;
const stateRows = $input.all();

let globalBotEnabled = true;
if (stateRows && stateRows.length > 0 && stateRows[0].json) {
  globalBotEnabled = stateRows[0].json.is_enabled !== false;
}

return [{ json: {
  ...webhook,
  globalBotEnabled
}}];

const input = $input.first().json;
const body = input.body || input;

const rawPhone = (body.celular || body.phone || body.contactPhone || body.from || '').toString();
const phone = rawPhone.replace(/[^0-9+]/g, '');

const contactId = (body.contact_id || body.contactId || '').toString().trim();
const email = (body.email || '').toString().trim().toLowerCase();
const conversationIdFromWebhook = (body.conversation_id || body.conversationId || '').toString().trim();

const locationId = (body.location && body.location.id) ? body.location.id : 'M649NrxtUHpNCNxTC5U1';

if (!contactId) {
  return [{ json: { isValid: false, errorCode: 400, errorMessage: 'Campo requerido faltante: contact_id' } }];
}

if (!phone) {
  return [{ json: { isValid: false, errorCode: 400, errorMessage: 'Campo requerido faltante: phone' } }];
}

return [{ json: {
  isValid: true,
  phone,
  email,
  contactId,
  conversationId: conversationIdFromWebhook,
  locationId,
  receivedAt: new Date().toISOString()
} }];

const validated = $('Validar y Normalizar').first().json;
const ghlResponse = $input.first().json;

let messages = [];
if (ghlResponse && ghlResponse.messages) {
  if (Array.isArray(ghlResponse.messages)) {
    messages = ghlResponse.messages;
  } else if (Array.isArray(ghlResponse.messages.messages)) {
    messages = ghlResponse.messages.messages;
  }
}

function mapMessageTypeToChannel(msgType, numericType) {
  const mt = (msgType || '').toString().toUpperCase();
  const nt = Number(numericType);
  if (mt === 'TYPE_WHATSAPP') return 'WhatsApp';
  if (mt === 'TYPE_SMS') return 'SMS';
  if (mt === 'TYPE_EMAIL') return 'Email';
  if (mt === 'TYPE_FACEBOOK') return 'FB';
  if (mt === 'TYPE_INSTAGRAM') return 'IG';
  if (mt === 'TYPE_LIVE_CHAT') return 'Live_Chat';
  if (mt === 'TYPE_CUSTOM_SMS') return 'SMS';
  if (mt === 'TYPE_CUSTOM_EMAIL') return 'Email';
  if (mt === 'TYPE_GMB') return 'GMB';
  if (nt === 1) return 'SMS';
  if (nt === 3) return 'Email';
  if (nt === 11) return 'FB';
  if (nt === 15) return 'GMB';
  if (nt === 18) return 'IG';
  if (nt === 19) return 'WhatsApp';
  if (nt === 20) return 'SMS';
  if (nt === 21) return 'Email';
  if (nt === 29) return 'Live_Chat';
  return 'WhatsApp';
}

if (messages.length === 0) {
  return [{ json: { ...validated, procesable: false, errorMessage: 'No pude encontrar tu mensaje en el sistema. Por favor escribime de nuevo.', messageType: 'error', inboundChannel: 'WhatsApp' } }];
}

let lastMsg = null;
for (const m of messages) {
  if (m.direction === 'inbound') { lastMsg = m; break; }
}

if (!lastMsg) {
  return [{ json: { ...validated, procesable: false, errorMessage: 'No encontré mensajes nuevos tuyos. Si querés escribir, por favor enviame tu consulta de nuevo.', messageType: 'error', inboundChannel: 'WhatsApp' } }];
}

const inboundChannel = mapMessageTypeToChannel(lastMsg.messageType, lastMsg.type);
const body = (lastMsg.body || '').toString();
const attachments = Array.isArray(lastMsg.attachments) ? lastMsg.attachments : [];

function detectAttachmentType(url) {
  if (!url) return 'unknown';
  const cleanUrl = url.toString().split('?')[0].toLowerCase();
  const ext = cleanUrl.split('.').pop();
  if (['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp', 'heic', 'heif'].includes(ext)) return 'image';
  if (['mp3', 'wav', 'ogg', 'oga', 'm4a', 'opus', 'aac', 'flac', 'webm'].includes(ext)) return 'audio';
  if (['mp4', 'mov', 'avi', 'mkv', '3gp'].includes(ext)) return 'video';
  if (['pdf', 'docx', 'doc', 'txt', 'xlsx', 'xls'].includes(ext)) return 'document';
  return 'unknown';
}

let messageType = 'text';
let attachmentUrl = '';

if (attachments.length > 0) {
  const firstUrl = typeof attachments[0] === 'string' ? attachments[0] : (attachments[0].url || attachments[0].fileUrl || '');
  attachmentUrl = firstUrl;
  const detected = detectAttachmentType(firstUrl);
  if (detected === 'image' || detected === 'audio') {
    messageType = detected;
  } else if (detected === 'video') {
    messageType = 'unsupported_video';
  } else if (detected === 'document') {
    messageType = 'unsupported_document';
  } else {
    messageType = 'unsupported_other';
  }
}

if (!body && !attachmentUrl) {
  return [{ json: { ...validated, procesable: false, errorMessage: 'Tu mensaje llegó vacío. Por favor escribime de nuevo.', messageType: 'error', inboundChannel } }];
}
if (messageType === 'unsupported_video') {
  return [{ json: { ...validated, procesable: false, errorMessage: 'Por el momento no puedo procesar videos. Si querés contarme con palabras o un audio de qué se trata, con gusto te ayudo.', messageType: 'error', inboundChannel } }];
}
if (messageType === 'unsupported_document') {
  return [{ json: { ...validated, procesable: false, errorMessage: 'Por el momento no puedo procesar documentos PDF u otros archivos. Si querés contarme con palabras de qué se trata, con gusto te ayudo.', messageType: 'error', inboundChannel } }];
}
if (messageType === 'unsupported_other') {
  return [{ json: { ...validated, procesable: false, errorMessage: 'Por el momento solo puedo procesar texto, imágenes y audios. Si querés contarme con palabras de qué se trata, con gusto te ayudo.', messageType: 'error', inboundChannel } }];
}
if (body.length > 2000) {
  return [{ json: { ...validated, procesable: false, errorMessage: 'Tu mensaje es muy largo. Por favor enviame uno más corto (máximo 2000 caracteres).', messageType: 'error', inboundChannel } }];
}

const cleanBody = body.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '').trim();

return [{ json: { ...validated, procesable: true, message: cleanBody, messageType, attachmentUrl, conversationId: lastMsg.conversationId || validated.conversationId || '', ghlMessageId: lastMsg.id || '', inboundChannel } }];

const procesado = $input.first().json;
return [{ json: {
  mensaje: procesado.errorMessage || 'No pude procesar tu mensaje. ¿Podés intentar de nuevo?',
  phone: procesado.phone || '',
  contactId: procesado.contactId || '',
  conversationId: procesado.conversationId || '',
  hasReservation: false,
  messageIn: '',
  transferToSales: false,
  agenteUsado: 'sistema',
  inboundChannel: procesado.inboundChannel || 'WhatsApp'
} }];

