const procesado = $('Procesar Último Mensaje').first().json;
const visionResponse = $input.first().json;
let descripcion = '';
try {
  descripcion = (visionResponse.choices && visionResponse.choices[0] && visionResponse.choices[0].message)
    ? (visionResponse.choices[0].message.content || '').trim()
    : '';
} catch (e) { descripcion = ''; }
if (!descripcion) descripcion = 'No se pudo procesar la imagen';
const captionOriginal = procesado.message || '';
let newMessage;
if (captionOriginal) {
  newMessage = '[El usuario envió una imagen. Descripción]: ' + descripcion + '\n\nMensaje del usuario: ' + captionOriginal;
} else {
  newMessage = '[El usuario envió una imagen. Descripción]: ' + descripcion + '\n\n(El usuario no escribió texto adicional)';
}
return [{ json: { ...procesado, message: newMessage, messageType: 'text', procesadoComo: 'imagen' } }];

const procesado = $('Procesar Último Mensaje').first().json;
const whisperResponse = $input.first().json;
let transcripcion = (whisperResponse && whisperResponse.text) ? whisperResponse.text.toString().trim() : '';
if (!transcripcion) transcripcion = 'No se pudo transcribir el audio';
const newMessage = '[El usuario envió un audio. Transcripción]: ' + transcripcion;
return [{ json: { ...procesado, message: newMessage, messageType: 'text', procesadoComo: 'audio' } }];

const items = $input.all();
let dbResult = null;
for (const it of items) {
  if (it && it.json && it.json.reservation_id) { dbResult = it.json; break; }
}

const procesado = $('Procesar Último Mensaje').first().json;
const inboundChannel = procesado.inboundChannel || 'WhatsApp';

let finalMessage = procesado.message || '';
let agenteMode = 'text';

try {
  const imgNode = $('Reemplazar Mensaje Imagen').first();
  if (imgNode && imgNode.json && imgNode.json.message) { finalMessage = imgNode.json.message; agenteMode = 'image'; }
} catch(e) {}

try {
  const audNode = $('Reemplazar Mensaje Audio').first();
  if (audNode && audNode.json && audNode.json.message) { finalMessage = audNode.json.message; agenteMode = 'audio'; }
} catch(e) {}

const hasReservation = !!(dbResult && dbResult.reservation_id);

let guestContext = '';
if (hasReservation) {
  guestContext = 'HUESPED CON RESERVA ACTIVA:\n- Nombre: ' + dbResult.guest_name + '\n- Reserva ID: ' + dbResult.reservation_id + '\n- Check-in: ' + dbResult.check_in + '\n- Check-out: ' + dbResult.check_out + '\n- Tipo de Habitación: ' + dbResult.room_type + '\n- Estado: ' + dbResult.status + '\n- Hotel: ' + dbResult.hotel_name;
} else {
  guestContext = 'SIN RESERVA ACTIVA. El cliente es un prospecto nuevo.';
}

const safeMessage = finalMessage || '';
const msg = safeMessage.toLowerCase();

const escalationKeywords = [
  'hablar con una persona', 'agente humano', 'persona real',
  'quiero hablar con alguien', 'operador', 'recepción directa', 'recepcion directa',
  'hablar con un humano', 'necesito ayuda real', 'no quiero bot',
  'talk to a human', 'real person', 'speak to someone',
  'quiero un agente', 'comunicarme con recepcion', 'comunicarme con recepción'
];
const needsHumanEscalation = escalationKeywords.some(kw => msg.includes(kw));

const bigdayKeywords = [
  'avistamiento', 'big day', 'bigday', 'big-day',
  '#bigdaycanonegro', 'ebird', 'concurso',
  'pajarero', 'birding', 'birdwatching',
  'global big day', 'dinamica', 'dinámica',
  'premio caño negro', 'premio cano negro',
  'foto de ave', 'fotos de aves'
];
const isBigDay = bigdayKeywords.some(kw => msg.includes(kw));

return [{ json: {
  phone: procesado.phone || '',
  email: procesado.email || '',
  message: safeMessage,
  contactId: procesado.contactId || '',
  conversationId: procesado.conversationId || '',
  hasReservation,
  guestContext,
  reservationData: hasReservation ? dbResult : null,
  needsHumanEscalation,
  isBigDay,
  agenteMode,
  inboundChannel
} }];

const ctx = $('Construir Contexto').first().json;
const promptRows = $input.all();

const prompts = {};
for (const row of promptRows) {
  if (row && row.json && row.json.agent_key && row.json.system_prompt) {
    prompts[row.json.agent_key] = row.json.system_prompt;
  }
}

// Contexto dinámico (inyectado automáticamente — el equipo NO lo edita en el panel)
const dynamicContext = '═══════════════════════════════════════\n' +
  'CONTEXTO DEL HUÉSPED (auto-generado, no editable desde el panel):\n' +
  '═══════════════════════════════════════\n' +
  ctx.guestContext + '\n\n' +
  'TELÉFONO: ' + ctx.phone + '\n\n' +
  '═══════════════════════════════════════\n\n';

const fallbackSoporte = 'Eres un asistente del hotel. El prompt no está configurado en el panel. Pedile al equipo que lo configure.';
const fallbackBigday = 'Eres un asistente de la dinámica Big Day. El prompt no está configurado en el panel.';
const fallbackVentas = 'Eres Lorena, asesora de reservas. El prompt no está configurado en el panel.';

return [{ json: {
  ...ctx,
  promptSoporte: dynamicContext + (prompts.soporte || fallbackSoporte),
  promptBigday: dynamicContext + (prompts.bigday || fallbackBigday),
  promptVentas: dynamicContext + (prompts.ventas || fallbackVentas)
} }];

const agentOutput = $input.first().json || {};
const ctx = $('Merge Prompts + Context').first().json || {};

let response = agentOutput.output || agentOutput.text || agentOutput.response || '';
let transferToSales = false;

if (!response || agentOutput.error) {
  response = '¡Hola! Disculpa, tengo dificultades para procesar tu consulta en este momento. ¿Podrías intentar nuevamente o comunicarte directamente con nuestra recepción?';
}

if (response.includes('[TRANSFERIR_A_VENTAS]')) {
  transferToSales = true;
  response = response.replace('[TRANSFERIR_A_VENTAS]', '').trim();
}

response = response
  .replace(/#{1,6}\s/g, '')
  .replace(/\*\*(.*?)\*\*/g, '*$1*')
  .replace(/\[(.*?)\]\((.*?)\)/g, '$1: $2')
  .replace(/```[\s\S]*?```/g, '')
  .replace(/`([^`]+)`/g, '$1')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (response.length > 4000) {
  response = response.substring(0, 3997) + '...';
}

let agenteUsado = 'soporte';
if (ctx.isBigDay) agenteUsado = 'bigday';
else if (!ctx.hasReservation) agenteUsado = 'ventas';

return [{ json: {
  mensaje: response,
  phone: ctx.phone || '',
  contactId: ctx.contactId || '',
  conversationId: ctx.conversationId || '',
  hasReservation: !!ctx.hasReservation,
  messageIn: ctx.message || '',
  transferToSales,
  agenteUsado,
  inboundChannel: ctx.inboundChannel || 'WhatsApp'
} }];
